INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 0, 0, 'Speak to the Shelter Guard to begin Rescue the Shelter Hold.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 1, 0, 'Rescue the Shelter Hold: read the training stones, then speak to the Shelter Lieutenant.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 2, 0, 'Rescue the Shelter Hold: continue through the training stones to the Shelter Sentry.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 3, 0, 'Defeat a Drudge Digger, collect its Imbued Digging Tool, then speak to the Shelter Scout. Leave room in your bag for three potions.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 4, 0, 'Defeat a Drudge Sentinel for its Menhir Glyph. Target the Menhir Portal and use the glyph from your backpack.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 5, 0, 'Speak to the Advance Shelter Scout in the Menhir Shard room.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('shelter', 6, 1, 'Rescue the Shelter Hold complete. Walk down the passageway and use the Menhir Shard to enter Dereth.', 'Pyrealium journal text (no retail journal line is recovered); steps per AC2 Vault quests/shelter and AC2Hero quest/osteth_rescuetheshelterhold', 'hand');
