INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v183', 5, 0, '1 Carrion Shreth', 'DAT string table 0x25008ade (questard_carrionshreth.stt) key 0xfeecb2de: phase 5 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v183', 6, 0, 'Report to Oriona.', 'DAT string table 0x25008ade (questard_carrionshreth.stt) key 0xf8ecb2de: phase 6, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v183', 7, 1, 'Oriona said: "Frazzled adventurers have been limping back town from the east, bearing terrifying tales of shreths foaming at the mouth, attacking all that fall within their path. We believe the Carrion Shreth are suffering from an outbreak of the dread claw and fang disease. We must do what we can to contain the disease before it spreads to Molwirth and Shoushi. You may want to band together with several adventurers to hunt these fell beasts, for they are now more dangerous than ever before. Put down 5 Carrion Shreth, and I shall reward you."', 'DAT string table 0x25008ade (questard_carrionshreth.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
