INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v201', 11, 0, 'Return to Sumalar.', 'DAT string table 0x25008aeb (questikb1_servitorspawn.stt) key 0xde47683e: phase 11, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v201', 12, 1, 'Sumalar said: "A collegue of mine in Linvak Tukal and I have observed that the Spawn in Dereth are on the increase. This may have disastrous implications. The Spawn have always been the natural enemies of the Naderu, who have been treasured by my people ever since our history began here on Dereth. If they are permitted to grow in numbers, I fear our dear Naderu may be in danger. Can we count on you?"', 'DAT string table 0x25008aeb (questikb1_servitorspawn.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v202', 1, 0, '10 Puppet Spawn', 'DAT string table 0x25008aec (questikb2_puppetspawn.stt) key 0xeb70c0e2: phase 1 shows the kills left (the DAT''s numbered phase lines count down, as Legions'' QuestGGWNightmare1-6 phases do)', 'vault');
