INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v202', 11, 0, 'Return to Sumalar.', 'DAT string table 0x25008aec (questikb2_puppetspawn.stt) key 0xeb70c062: phase 11, after the last kill', 'vault');
INSERT INTO quest_stage (quest, stage, completed, journal_text, source, family) VALUES ('v202', 12, 1, 'Sumalar said: "The Puppet Spawn also continue to grow in numbers, and they must be contained before they threaten the Naderu''s very existence. We must thin their numbers before it is too late. Destroy 10 Puppet Spawn, and I will reward you."', 'DAT string table 0x25008aec (questikb2_puppetspawn.stt) key 0x6c459364 (the quest''s summary; Pyrealium shows it for the completed quest)', 'vault');
